  "vidcfg.anchorAutoHint": "המנוע בוחר. כיום המשמעות היא סטיל פתיחה שנוצר לכל סצנה, ובנוסף סטיל סיום בסצנות ארוכות יותר שבהן הספק תומך בכך.",
  "vidcfg.anchorStartEndHint": "כל סצנה מרונדרת בין סטיל פתיחה לסטיל סיום שנוצרו. מתאים כשצילום חייב לנחות על תמונה סופית מסוימת — פוזה מוחזקת, גיבור מוצר, פריים כותרת. במצלמה בתנועה סטיל הסיום הוא ניחוש לגבי המקום שאליו העולם מגיע, וזה מה שגורם לצילומים להתעוות.",
  "vidcfg.anchorStartOnlyHint": "כל סצנה נפתחת בסטיל שנוצר מהפריים האחרון האמיתי של הצילום הקודם, ואז מסתיימת במקום שאליו התנועה שלה מגיעה באופן טבעי. מסיר את העיוות שנובע מהתכנסות אל פריים סיום שנוצר מראש.",
  "vidcfg.anchorReferenceHint": "ללא פריימים שנוצרו כלל — ייחוסי דמות ומיקום יחד עם הפרומפט נושאים כל צילום. החופש הגדול ביותר למצלמה, לתאורה ולאווירה; השליטה הפחותה ביותר בקומפוזיציה המדויקת.",
  "vidcfg.renderKeyframesNote": "פריימי מפתח מרנדר כל סצנה מפריימי התחלה/סיום שנוצרו — הסצנות מרונדרות מחדש באופן עצמאי. המוזיקה מתווספת אחרי הרינדור, לא על ידי מודל הווידאו.",
  "vidcfg.renderKeyframesForced": "ל-{model} אין תעבורת וידאו-ייחוס, ולכן הוא תמיד מרנדר עם פריימי מפתח: כל סצנה מפריימי ההתחלה/סיום שנוצרו עבורה, וכל תפר הוא חיתוך חד.",
  "vidcfg.anchorReferenceUnavailable": "להרצה מונחית־ייחוסים אין נתיב לפריים סיום שאפשר להצמיד אליו, ולכן האפשרות הזו אינה זמינה כל עוד פריים סיום מחובר.",
  "vidcfg.plannerStyleHint": "נאמן שומר על התזמון (מוסט לכל מקטע); מכווץ משכתב לגיליון ליהוק קומפקטי + קצב זורם; מעוגן-סלוט פותח כל מקטע בהגדרות הסלוטים ומתייחס לשמות הסלוטים בפעולה; היברידי משלב קצב קומפקטי עם תוויות ישויות עקביות ונשען על תמונות ייחוס למראה; היברידי פלוס מוסיף מניפסט זהות אלמנטים מובנה מעל כל המשך; היברידי מקס הוא היברידי פלוס ללא הדחיסה וללא תקרת הגודל — המתכנן משמר כל פרט מהניתוח (פרומפטים ארוכים יותר, נאמנות מרבית).",
