  "vidcfg.res1080pLockedRetake": "1080p (נעול לצילום חוזר)",
  "vidcfg.descVideoRetake": "מרנדר מחדש קטע מווידאו במעלה הזרם באמצעות LTX 2.3 Pro. חברו מקור וידאו למחבר הוורוד, ואז בחרו את הקטע להחלפה. משך מינימלי הוא 2 שניות.",
  "vidcfg.probeReadError": "לא הצלחנו לקרוא את הווידאו הזה",
  "vidcfg.resultSelectionHint": "הווידאו מנותח מספר פעמים. ״בחירה״ שומרת את המעבר החזק ביותר כפי שהוא; ״שילוב״ גם משלבת פרטים מהמעברים האחרים לאחר אימותם מול הצילום (איטי מעט יותר, השלם ביותר).",
  "vidcfg.castVariations": "וריאציות ליהוק — זיהוי מראות חלופיים לכל ישות",
  "vidcfg.castVariationsHint": "זהו גם וריאציות מראה לכל ישות (חלום, פלאשבק, תחפושת, תלבושת…) וקשרו אותן לסצנות שבהן כל מראה פעיל. שימו לב: במדרגות של מעבר יחיד הדבר עלול להפחית את מספר הישויות שמחולצות — השאירו כבוי אלא אם אתם זקוקים למראות.",
  "vidcfg.translateSpeech": "דיבור — מה שנאמר או מושר",
  "vidcfg.translateOnScreenText": "טקסט על המסך — שלטים, כתוביות, כותרות",
  "vidcfg.translateHint": "כשהאפשרויות כבויות, הניתוח שומר על שפת המקור של הווידאו מילה במילה. סמנו אותן באופן עצמאי — למשל דיבור באנגלית מעל רחוב שהשלטים בו נשארים בכתב שלהם. כל בחירה עוברת לווידאו המשוחזר: מה שהוא אומר, ומה שהוא מראה. שמות מותגים, מוצרים ומקומות שומרים על צורתם המקורית בכל מקרה.",
  "vidcfg.probedDuration": "משך {duration} — מדרגת התמחור נקבעת לפי האורך הזה.",
  "vidcfg.auditingAnalysisFrom": "מבקר את הניתוח מ־״{name}״",
  "vidcfg.noAnalysisWired": "לא חובר ניתוח",
  "vidcfg.auditWiredDesc": "הביקורת צופה שוב בקליפ מול הניתוח הזה ומחילה רק תיקונים שאומתו מול הווידאו, תוך חשיפת כל שינוי. {min}–{max} קרדיטים לפי אורך הווידאו.",
  "vidcfg.auditUnwiredDesc": "חברו ניתוח וידאו (או ביקורת AI אחרת) למחבר הניתוח כדי לבקר אותו. ללא חיבור, הרכיב הזה מריץ תחילה ניתוח מהיר משלו — אותה ביקורת, אבל {autoMin}–{autoMax} קרדיטים לפי אורך הווידאו במקום {min}–{max}.",
  "vidcfg.auditConnectVideo": "חברו וידאו למחבר הווידאו — הביקורת צופה שוב בצילום עצמו, ולכן היא לא יכולה לרוץ בלעדיו.",
  "vidcfg.descVideoAudit": "צופה שוב בקליפ (עד 10 דקות) מול הניתוח שלו ומחזיר את הניתוח המתוקן יחד עם דוח על מה שתוקן, מה שמנגנוני ההגנה מנעו, ועל מה כדאי לשים לב. ללא הגדרות — הביקורת הולכת אחרי הצילום.",
