  "tut.iedTealWhy": "תיקון צבע, לא צביעה מחדש. אותה תמונה עם מראה קולנועי — שינוי מהסוג שאחרת הייתם מתארים גרוע בשלוש שורות של פרומפט.",
  "tut.iedAnimeName": "אנימה, מצוירת",
  "tut.iedSubTwoStyles": "שני רכיבי ״סגנון״ בבת אחת",
  "tut.iedAnimeWhy": "שני רכיבי ״סגנון״ מזינים את העריכה הזו, והתוצאה משלבת את שניהם. סגנון הוא לא משבצת יחידה — שלבו כמה ותקבלו מראה שאף אחד מהם לא מתאר לבדו.",
  "tut.iedAtomicName": "העידן האטומי, שנות ה־50",
  "tut.iedSubEra": "מונע על ידי רכיב ״תקופה״",
  "tut.iedAtomicWhy": "תקופה מביאה איתה יחד מלתחה, פלטת צבעים וסוג פילם. העריכה הזו גם רצה על מודל אחר מזה של שכנותיה — בחירה של כל רכיב בנפרד, לא הגדרה לכל הקנבס.",
  "tut.iedCyberName": "סייברפאנק",
  "tut.iedSubStyle": "מונע על ידי רכיב ״סגנון״",
  "tut.iedCyberWhy": "אותו רכיב ״סגנון״ כמו בעריכת האנימה, עם ערך אחר. סוג רכיב אחד מכסה את כל הקטלוג, כך שניסיון של מראה אחר הוא לחיצה אחת.",
  "tut.ied85mmName": "פורטרט ב־85mm",
  "tut.iedSubLens": "מונע על ידי רכיב ״עדשה״",
  "tut.ied85mmWhy": "אופטיקה, לא תוכן. אורך המוקד משנה את הדחיסה ואת עומק השדה — הנושא המצולם לא משתנה, והצילום הוא צילום אחר.",
  "tut.iedNoBgName": "הרקע הוסר",
  "tut.iedSubNoSettings": "בלי הגדרות בכלל",
  "tut.iedNoBgWhy": "אין מה להגדיר ואין מה לכתוב. הנושא נחתך על רקע שקוף, מוכן להצבה על כל דבר.",
  "tut.iedTokyoName": "טוקיו בלילה",
  "tut.iedTokyoWhy": "החלפת רקע דורשת שני דברים בבת אחת: את המקום החדש, ואת התאורה על הנושא בהתאמה אליו. בקשו רק את הראשון, והמראה המודבק יסגיר את זה.",
  "tut.iedHeadline": "תמונה אחת נכנסת. תשע עריכות שונות יוצאות.",
  "tut.iedSubline": "כל עריכה קוראת את אותו מקור, כך ששום דבר לא נערם ושום דבר לא נפגם. לחצו על כל תוצאה כדי לראות בדיוק מה יצר אותה.",
  "tut.iedChipEdits": "9 עריכות",
  "tut.iedChipSharedOriginal": "מקור משותף אחד",
  "tut.iedChipNonDestructive": "שום דבר לא הרסני",
  "tut.iedInSub": "נוצר פעם אחת, ולא נגעו בו שוב",
  "tut.iedOutSub": "לחצו על אחת כדי לראות מה יצר אותה",
